void fn0() {

  List<List<int>> graph = [
    [0, 1],
    [0, 2],
    [1, 2],
    [2, 0],
    [2, 3],
    [3, 2],
  ];

  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> stack = [];

  int index = 0;
  while (index < n) {

    for (int i = 0; i < n; i++) {
      if (!visited[i] && graph[i].isNotEmpty) {
        visited[i] = true;
        stack.add(i);
        index++;
