  ];
  int n = graph.length;
  List<int> indegree = List<int>.filled(n, 0);

  for (var edge in graph) {
    int u = edge[0];
    int v = edge[1];
    indegree[v]++;
  }

  List<int> topologicalSort(List<int> indegree) {
    List<int> sorted = <int>[];
    List<int> queue = <int>[];

    for (int i = 0; i < n; i++) {
      if (indegree[i] == 0) {
        queue.add(i);
      }
    }

    while (queue.isNotEmpty) {
      int current = queue.removeFirst();
      sorted.add(current);

      for (var edge in graph) {
        int u = edge[0];
        int v = edge[1];
        if (indegree[v] > 0) {
          indegree[v]--;
          if (indegree[v] == 0) {
            queue.add(v);
          }
        }
      }
    }

    return sorted;
  }

  List<int> sorted = topologicalSort(indegree);
  print('Topological Sort: ${sorted.join(' -> ')}');
}

