  List<List<int>> graph = [
    [0, 1],
    [0, 2],
    [2, 3],
    [2, 4],
    [1, 2],
    [4, 2],
  ];

  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> stack = [];
  List<int> sorted = [];

  void dfs(int v, List<List<int>> graph, List<bool> visited, List<int> stack) {
    visited[v] = true;

    for (int neighbor in graph[v]) {
      if (!visited[neighbor]) {
        dfs(neighbor, graph, visited, stack);
      }
    }

    stack.add(v);
  }

  for (int i = 0; i < n; i++) {
    if (!visited[i]) {
      dfs(i, graph, visited, stack);
    }
  }

  List<int> reversePostorder = [];
  List<int> reverseStack = [];
  reverseStack.addAll(stack.reversed);

  while (reverseStack.isNotEmpty) {
    int current = reverseStack.removeLast();
    reversePostorder.add(current);
  }

  if (reversePostorder.length < n) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${reversePostorder.join(' -> ')}');
  }
}

