      if (dp[j] && wordDict.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  void backtrack(int start, List<String> current, List<String> result) {
    if (start == s.length) {
      result.add(List.from(current));
      return;
