List<String> wordBreakHelper(String s, List<String> wordDict) {
  List<List<bool>> dp = List.generate(s.length + 1, (_) => List<bool>.filled(s.length + 1, false));
  for (int i = 0; i <= s.length; i++) dp[i][0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j][0]) dp[i][0] = true;
      if (dp[j][i - j]) dp[i][i - j] = true;
    }
  }

  List<String> result = [];
  if (dp[s.length][s.length]) {
    result.add("");
    return result;
  }

  for (int i = s.length; i > 0; i--) {
    if (dp[i - 1][i]) {
      result.add(s.substring(i - 1, i));
    }
  }
  return result;
}

int minWordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i)) && dp[j] != s.length + 1) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[s.length] > s.length ? -1 : dp[s.length];
}

