bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  Map<String, List<String>> dp = {};

  for (String word in wordDict) {
    dp[word] = [];
  }

  for (int i = 0; i < s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i)) && dp.containsKey(s.substring(j, i)) && dp[s.substring(j, i)].isNotEmpty) {
        dp[s.substring(i, j + 1)] = [...dp[s.substring(i, j + 1)], ...dp[s.substring(j, i)]];
      }
    }
  }

  List<String> result = [];
  for (String word in wordDict) {
    if (dp[word] != null) {
      result.add(word);
    }
  }

  return result.length == wordDict.length;
}

