    print("Pattern not found. n = 0");
    return;
  }
  if (m < n) {
    print("Pattern not found. m < n");
    return;
  }

  List<List<int>> dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  for (int i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (int j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (str[i - 1] == pattern[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        int bestPrev = dp[i - 1][j - 1];
        int bestCur = dp[i][j - 1];
        dp[i][j] = bestPrev < bestCur ? bestPrev : bestCur;
      }
    }
  }

  int i = m;
  int j = n;
  List<int> positions = [];

  while (i > 0 && j > 0) {
    if (str[i - 1] == pattern[j - 1]) {
      i--;
      j--;
    } else if (dp[i - 1][j] < dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

