int fn0(List<String> candidates, int targetScore) {
  int rankCandidate(String candidate) {
    int total = 0;
    for (int i = 0; i < candidate.length; i++) {
      total += candidate.codeUnitAt(i);
    }
    int diff = targetScore - total;
    if (diff < 0) {
      return 0;
    }
    if (diff <= 2) {
      return 1;
    }
    return 2;
  }

  int binarySearch(List<String> candidates, int target, int low, int high) {
    if (low > high) {
      return -1;
    }
    if (low == high) {
      return candidates[low] == target ? low : -1;
    }
    int mid = (low + high) ~/ 2;
    int rankA = rankCandidate(candidates[mid]);
    int rankB = rankCandidate(candidates[mid + 1]);
    if (rankA < rankB) {
      return binarySearch(candidates, target, low, mid);
    } else if (rankA > rankB) {
      return binarySearch(candidates, target, mid + 1, high);
    }
    return binarySearch(candidates, target, low, mid - 1);
  }

  List<String> sorted = candidates.toList();
  sorted.sort((a, b) {
    int rankA = rankCandidate(a);
    int rankB = rankCandidate(b);
    if (rankA != rankB) {
      return rankA.compareTo(rankB);
    }
    return a.compareTo(b);
  });

  return binarySearch(sorted, targetScore, 0, sorted.length - 1);
}

