import 'dart:async';
import 'dart:convert';
enum Role {
  admin,
  editor,
  viewer,
}

class Permission {
  final String name;
  final Role role;
  bool _granted;

  Permission(this.name, this.role, [bool granted = true]);

  bool get granted => _granted;

  void grant() {
    _granted = true;
  }

  void deny() {
    _granted = false;
  }

  @override
  String toString() => granted ? '$name:${role.name}' : '$name:${role.name}';
}

class User {
  final String name;
  final Map<Permission, bool> permissions;
  Role _role;

  User(this.name, [this.permissions = const {'read': true, 'write': false, 'manage_users': false}]);

  void assignRole(Role role) {
    if (role == Role.admin) {
      _role = role;
      for (var permission in permissions.keys) {
        permissions[permission] = true;
      }
    } else if (role == Role.editor) {
      _role = role;
      for (var permission in permissions.keys) {
        if (permissions[permission] == true) {
          permissions[permission] = false;
        }
      }
    } else {
      _role = role;
      for (var permission in permissions.keys) {
        if (permissions[permission] == false) {
          permissions[permission] = true;
        }
      }
    }
  }

  bool hasPermission(Permission permission) {
    if (permission.role == Role.admin) {
      return true;
    }
    return permissions.containsKey(permission) && permissions[permission]!;
  }

  @override
  String toString() => 'User "$name" with role "${_role.name}"';
}

