bool hasPath(int u, int v) {
  if (u < 0 || u >= 5 || v < 0 || v >= 5) return false;
  bool visited = false;
  List<int> queue = [u];
  visited = true;
  while (queue.isNotEmpty) {
    int front = queue.removeAt(0);
    if (front == v) return true;
    for (int neighbor in graph[front]) {
      if (!visited) {
        queue.add(neighbor);
        visited = true;
      }
    }
  }
  return false;
}

