Map<String, int> fn0(List<int> songDurations, int targetMinutes) {
  if (targetMinutes <= 0) {
    return {"pairCount": 0, "mashupDuration": 0};
  }
  int n = songDurations.length;
  if (n == 0) return {"pairCount": 0, "mashupDuration": 0};

  int binarySearch(int low, int high) {
    if (low > high) return -1;
    int mid = low + (high - low) ~/ 2;
    if (songDurations[mid] == targetMinutes) {
      return mid;
    } else if (songDurations[mid] < targetMinutes) {
      return binarySearch(mid + 1, high);
    } else {
      return binarySearch(low, mid - 1);
    }
  }

  int pairCount = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (songDurations[i] + songDurations[j] == targetMinutes) {
        pairCount++;
      }
    }
  }

  int totalMashupDuration = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (songDurations[i] + songDurations[j] == targetMinutes) {
        int firstIdx = binarySearch(0, i - 1);
        int secondIdx = binarySearch(i + 1, j - 1);
        if (firstIdx != -1 && secondIdx != -1) {
          totalMashupDuration += songDurations[firstIdx] + songDurations[secondIdx];
        }
      }
    }
  }

  return {"pairCount": pairCount, "mashupDuration": totalMashupDuration};
}

