Map<String, int> fn0(List<int> songDurations, int targetDuration) {
  int n = songDurations.length;
  if (n == 0 || targetDuration <= 0) return {"pairCount": 0, "mashupDuration": 0};

  int helper(int l, int r) {
    if (l >= r) return 0;
    if (l == r - 1) {
      return songDurations[l] == targetDuration ? 1 : 0;
    }

    int m = (l + r) ~/ 2;
    int count = helper(l, m) + helper(m + 1, r);
    if (count == 0 && songDurations[l] < targetDuration && songDurations[m + 1] < targetDuration) {
      count++;
    }
    return count;
  }

  int result = helper(0, n - 1);
  int total = 0;
  for (int i = 0; i < n; i++) {
    total += songDurations[i];
  }
  return {"pairCount": result, "mashupDuration": total};
}

