    if (index >= arrivalDays.length) return 0;

    int day = arrivalDays[index];
    if (day > currentDay) {
      return getPairCount(index + 1, day, lastMergeDay);
    }
    if (day == currentDay) {
      return 1 + getPairCount(index + 1, currentDay + 1, lastMergeDay);
