class Quaternion {
  final Complex w, x, y, z;

  const Quaternion(this.w, this.x, this.y, this.z);

  factory Quaternion.zero() => const Quaternion(0.0, 0.0, 0.0, 0.0);

  factory Quaternion.random() => Quaternion(
      math.random() * 2 - 1,
      math.random() * 2 - 1,
      math.random() * 2 - 1,
      math.random() * 2 - 1);

  Quaternion operator +(other) => Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator -(other) => Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  Quaternion operator *(double scalar) => Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);

  Quaternion operator *(other) {
    final q2 = other as Quaternion;
    return Quaternion(
      w * q2.w - x * q2.x - y * q2.y - z * q2.z,
      w * q2.x + x * q2.w + y * q2.z - z * q2.y,
      w * q2.y + x * q2.z + y * q2.w - z * q2.x,
      w * q2.z + x * q2.y + y * q2.x - z * q2.w,
    );
  }

  Quaternion inverse() => Quaternion(w, -x, -y, -z);

  Quaternion conjugate() => Quaternion(w, x, y, -z);

  double norm() => math.sqrt(w * w + x * x + y * y + z * z);

  Quaternion normalized() {
    final norm = norm();
    if (norm == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(w / norm, x / norm, y / norm, z / norm);
  }

  @override
  String toString() => 'Quaternion($w, $x, $y, $z)';
}

