    return Quaternion(x, -y, -z, w);
  }

  Quaternion normalized() {
    var n = norm();
    if (n == 0) return Quaternion(0.0, 0.0, 0.0, 0.0);
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() {
    var n = norm();
    if (n == 0) return Quaternion(0.0, 0.0, 0.0, 0.0);
    return Quaternion(x / n, -y / n, -z / n, w / n);
  }

  double angle() {
    return math.acos(norm());
  }

  Quaternion rotate(Quaternion other) {
    var a = this.normalized();
    var b = other.normalized();
    return Quaternion(
      a.x * b.x - a.z * b.z,
      a.x * b.y + a.z * b.w,
      a.z * b.x - a.x * b.z,
      a.z * b.y + a.x * b.w,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

