  static Quaternion fromList(List<double> list) {
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(real + other.real,
        imaginary1 + other.imaginary1,
        imaginary2 + other.imaginary2,
        imaginary3 + other.imaginary3);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(real - other.real,
        imaginary1 - other.imaginary1,
        imaginary2 - other.imaginary2,
        imaginary3 - other.imaginary3);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(real * scalar,
        imaginary1 * scalar,
        imaginary2 * scalar,
        imaginary3 * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double a = real, b = other.real;
    double c = imaginary1, d = other.imaginary1;
    double e = imaginary2, f = other.imaginary2;
    double g = imaginary3, h = other.imaginary3;
    return Quaternion(
      (a * b - c * d - e * g + f * h),
      (a * d + b * c + e * h - f * g),
      (a * g - b * h + e * f + d * c),
      (b * h - e * g + f * c),
    );
  }

  Quaternion operator ^(double angle) {
    double half = angle / 2;
    double sin = sin(half);
    double cos = cos(half);
    return Quaternion(
      cos,
      sin * imaginary1,
      sin * imaginary2,
      sin * imaginary3,
    );
  }

  Quaternion get conjugate => Quaternion(real, -imaginary1, -imaginary2, -imaginary3);

  double get norm => sqrt(real * real + imaginary1 * imaginary1 + imaginary2 * imaginary2 + imaginary3 * imaginary3);

  @override
  String toString() {
    return 'Quaternion($real, $imaginary1, $imaginary2, $imaginary3)';
  }
}

