class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion(double q) : this(q, 0.0, 0.0, q);

  const Quaternion() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle)
      : this(
          axisX * cos(angle / 2),
          axisY * cos(angle / 2),
          axisZ * cos(angle / 2),
          sin(angle / 2)
        );

  const Quaternion.fromUnit(double x, double y, double z)
      : this(x, y, z, sqrt(x * x + y * y + z * z));

  const Quaternion.fromNormalized(double x, double y, double z, double w)
      : this((x * w + y * z) / 2, (x * z - y * w) / 2, (y * w - x * z) / 2, (w * w - x * x - y * y) / 2);

  const Quaternion.fromVector(Vector3 vector)
      : this(vector.x, vector.y, vector.z, sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z));

  Quaternion operator +(covariant Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(covariant Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(covariant Quaternion other) =>
      Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * z - y * w + z * other.x + w * other.y,
        x * w + y * z - z * other.x - w * other.y,
      );

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  const Quaternion normalized() => this * (1.0 / norm());

  const Quaternion conjugate() =>
      Quaternion(x, -y, -z, w);

  const Quaternion inverse() =>
      this * (1.0 / (norm() * norm()));

  double dot(covariant Quaternion other) =>
      x * other.x + y * other.y + z * other.z + w * other.w;

  @override
  String toString() =>
      '${x.abs().toStringAsFixed(2)} + ${y.abs().toStringAsFixed(2)}i + ${z.abs().toStringAsFixed(2)}j + ${w.abs().toStringAsFixed(2)}k';

  static const double EPSILON2 = EPSILON * EPSILON;

  bool get isAlmostZero => norm() < EPSILON2;

  static double sqrt(double x) {
    if (x < 0) x = -x;
    if (x < EPSILON2) return 0.0;
    return x * 0.5 * (1.0 + sqrt(x * 2.0));
  }

  static double sqrt(double x, double y) =>
      sqrt(sqrt(x) * x + sqrt(y) * y);

  static double sqrt(double x, double y, double z) =>
      sqrt(sqrt(x) * x + sqrt(y) * y + sqrt(z) * z);
}

