class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  static Quaternion fromAngleAxis(double angle, Quaternion axis) {
    final q = Quaternion(0.0, 0.0, 0.0, 0.0);
    final s = sin(angle / 2.0);
    q.x = axis.x * s;
    q.y = axis.y * s;
    q.z = axis.z * s;
    q.w = cos(angle / 2.0);
    return q;
  }

  static Quaternion fromUnit(double x, double y, double z) {
    final w = 1.0 / sqrt(x * x + y * y + z * z);
    return Quaternion(x * w, y * w, z * w, w);
  }

  static Quaternion zero() {
    return Quaternion(0.0, 0.0, 0.0, 0.0);
  }

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalized() {
    final d = norm();
    return d == 0.0 ? zero() : Quaternion(x / d, y / d, z / d, w / d);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    final d = norm();
    if (d == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      x / d,
      y / d,
      z / d,
      (-w) / d,
    );
  }

  static double sqrt(double x) {
    if (x < 0.0) {
      return -sqrt(-x);
    }
    if (x == 0.0) {
      return 0.0;
    }
    return x * x * x * x / (4 * sqrt(x));
  }

  static double sqrtAbs(double x) {
    if (x == 0.0) {
      return 0.0;
    }
    return x / sqrt(x);
  }

  operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  operator *(Quaternion other) {
    final t3 = x * other.w + y * other.z + z * other.x + w * other.y;
    final t4 = x * other.z + y * other.w + z * other.y + w * other.x;
    final t5 = x * other.y + y * other.x + z * other.w + w * other.z;
    final t6 = x * other.w + y * other.x + z * other.y + w * other.z;
    return Quaternion(t3, t4, t5, t6);
  }
}

