class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  /// Static constructor for creating a Quaternion from three real parts.
  factory Quaternion.fromParts(double x, double y, double z) {
    return Quaternion(x, y, z, 0.0);
  }

  /// Static constructor for creating a Quaternion from four real parts.
  factory Quaternion.fromValues(double x, double y, double z, double w) {
    return Quaternion(x, y, z, w);
  }

  /// Constructs a Quaternion from a complex number (x + yi).
  factory Quaternion.fromComplex(double re, double im) {
    return Quaternion(re, im.abs(), -im.abs(), 0.0);
  }

  /// Gets the conjugate of the Quaternion.
  Quaternion get conjugate => Quaternion(-x, -y, -z, w);

  /// Gets the inverse of the Quaternion.
  Quaternion get inverse => conjugate * conjugate;

  /// Returns the magnitude (norm) of the Quaternion.
  double get norm => sqrt(x * x + y * y + z * z + w * w);

  /// Normalizes the Quaternion to have unit norm.
  Quaternion get normalized =>
      (1 / norm) * Quaternion.fromValues(x, y, z, w);

  /// Adds two Quaternion objects.
  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  /// Subtracts two Quaternion objects.
  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  /// Multiplies two Quaternion objects.
  Quaternion operator *(Quaternion other) =>
      Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * z + y * w + z * other.x - w * other.y,
        x * w + y * z + z * other.y - w * other.x,
      );

  /// Multiplies a Quaternion by a scalar (double).
  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  /// Multiplies two quaternions component-wise.
  static Quaternion operator *(Quaternion q1, Quaternion q2) =>
      Quaternion(
        q1.x * q2.x - q1.y * q2.y - q1.z * q2.z - q1.w * q2.w,
        q1.x * q2.y + q1.y * q2.x + q1.z * q2.w - q1.w * q2.z,
        q1.x * z + q1.y * w + q2.x * z - q2.y * w,
        q1.x * w + q1.y * z + q2.x * w - q2.y * z,
      );

  /// Equals method for Quaternion objects.
  bool operator ==(Object other) {
    if (other is! Quaternion) return false;
    return x == other.x && y == other.y && z == other.z && w == other.w;
  }

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

