double fn0(List<int> sortedDurations) {
  if (sortedDurations.isEmpty) {
    return 0.0;
  }
  double calculate(int start, int end) {
    if (start >= end) {
      return 0.0;
    }
    int total = 0;
    for (int i = start; i < end; i++) {
      total += sortedDurations[i];
    }
    int mid = (start + end) ~/ 2;
    return (total * mid).toDouble() +
        calculate(start, mid) +
        calculate(mid + 1, end);
  }
  return calculate(0, sortedDurations.length);
}

