double fn0(List<int> sortedMinLengths) {
  if (sortedMinLengths.isEmpty) return 0.0;
  int total = 0;
  for (int i = 0; i < sortedMinLengths.length; i++) {
    total += sortedMinLengths[i];
  }
  int target = total ~/ 2;
  int left = 0;
  int right = sortedMinLengths.length;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedMinLengths[mid] < target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return left.toDouble();
}

