int kmpSearch(String text, String pattern) {
  int n = text.length;
  int m = pattern.length;

  if (m == 0 || n == 0 || m > n) {
    return -1;
  }

  List<int> lps = List.filled(m, 0);
  int len = 0;
  int i = 0;

  while (i < n) {
    if (pattern[len] == text[i]) {
      i++;
      len++;
    }
    if (len == m) {
      return i - len; 
    } else if (i < n && pattern[len] != text[i]) {
      if (len != 0) {
        len = lps[len - 1];
      } else {
        i++;
      }
    }
  }
  return -1; 
}

