void fn0() {

  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  int dfaLength = 256;

  int numStates = text.length + 1; 

  List<List<int>> dfa = List.generate(numStates, (_) => List.filled(dfaLength, 0));

  int numLPSArray = 256;

  List<int> lps = List.filled(numLPSArray, 0);

  void buildAutomaton() {
    int lenPattern = pattern.length;

    for (int i = 0; i < numStates; i++) {
      for (int c = 0; c < dfaLength; c++) {
        dfa[i][c] = 0;
      }
    }

    dfa[0][pattern.codeUnitAt(0)] = 1;

    for (int i = 1; i < lenPattern; i++) {
      for (int c = 0; c < dfaLength; c++) {
        int newState = pattern.codeUnitAt(i) ^ c;

        if (newState < 0) newState = 0;

        int nextCount = dfa[i - 1][c] + 1;

        if (nextCount > dfa[newState][c]) {
          dfa[newState][c] = nextCount;
        }

        int beforeCount = dfa[newState][c];
        if (beforeCount > 0 && (newState == 0 || newState == 255)) {
          int lc = lps[beforeCount - 1];
          if (lc > 0) dfa[newState][c] += lc;
        }
      }
    }
  }

  void computeLPSArray() {
    int lenPattern = pattern.length;

    lps[0] = 0;
    for (int i = 1; i < numLPSArray; i++) {
      int j = lenPattern - 1;
      while (j > 0 && pattern[j] != pattern[i - 1]) {
        j--;
      }
      lps[i] = j;
    }
  }

  void kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    List<int> matches = [];

    for (int i = 0; i <= n - m; i++) {
      int c = 0; 
      for (int j = i; j < i + m; j++) {
        if (pattern[c] != text[j]) {
          c = lps[c];
        }
        if (c == m - 1) {
          matches.add(i);
          c = lps[c];
        }
      }
    }

    print("Text: $text");
    print("Pattern: $pattern");
    print("Pattern length: ${pattern.length}\n");

    print("LPS array for pattern: $lps\n");

    if (matches.isEmpty) {
      print("Pattern not found in text.\n");
    } else {
      print("\nPattern found at indices: $matches");
    }
  }

