class Role {
  String name;
  List<String> permissions;
  Role(this.name, this.permissions);
}

class Resource {
  String name;
  bool accessible;
  Resource(this.name, [this.accessible = true]);
}

class User {
  String name;
  List<String> roles;
  User(this.name, [this.roles = const []]);
}

class AccessControlSystem {
  Map<String, List<String>> resourceAccessMatrix = {};
  Map<String, Map<String, List<String>>> userRoles = {};
  Map<String, List<String>> auditLog = {};

  void grantRole(String user, String roleName) {
    if (!userRoles.containsKey(user)) {
      userRoles[user] = {};
    }
    userRoles[user]![roleName] = [];
  }

  void revokeRole(String user, String roleName) {
    if (userRoles.containsKey(user)) {
      Map<String, List<String>> userRolesData = userRoles[user]!;
      if (userRolesData.containsKey(roleName)) {
        userRolesData.remove(roleName);
      }
    }
  }

  void assignPermissions(String user, String role, List<String> permissions) {
    if (!userRoles.containsKey(user)) {
      userRoles[user] = {};
    }
    userRoles[user]![role] = permissions;
  }

  void removePermission(String user, String role, String permission) {
    if (userRoles.containsKey(user)) {
      Map<String, List<String>> userRolesData = userRoles[user]!;
      if (userRolesData.containsKey(role)) {
        List<String> permissions = userRolesData[role]!;
        permissions.remove(permission);
      }
    }
  }

  void audit(String action, String resource, String user, String role) {
    String timestamp = DateTime.now().toIso8601String();
    auditLog[timestamp] = [action, resource, user, role];
  }

  bool checkAccess(String user, String resource) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      return false;
    }
    List<String> rolesRequired = resourceAccessMatrix[resource]!;
    for (String role in rolesRequired) {
      if (!userRoles.containsKey(user)) {
        return false;
      }
      Map<String, List<String>> userRolesData = userRoles[user]!;
      if (!userRolesData.containsKey(role)) {
        return false;
      }
      List<String> permissions = userRolesData[role]!;
      bool hasAllPermissions = true;
      for (String required in permissions) {
        if (!resourceAccessMatrix.containsKey(resource) ||
            !resourceAccessMatrix[resource]!.contains(required)) {
          hasAllPermissions = false;
          break;
        }
      }
      if (!hasAllPermissions) {
        return false;
      }
    }
    return true;
  }
}

