import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, this.permissions);

  @override
  String toString() => '$name: $permissions';
}

class Resource {
  final String name;
  final String type;
  final String? sensitiveData; 

  Resource(this.name, this.type, [this.sensitiveData]);

  @override
  String toString() => '$name ($type)';
}

class User {
  final String name;
  final Map<Resource, List<String>> permissions = {};

  User(this.name);

  void grant(Resource resource, [String role = 'user']) {
    if (permissions.containsKey(resource)) {
      permissions[resource]!.add(role);
    } else {
      permissions[resource] = [role];
    }
  }

  void revoke(Resource resource, [String role = 'user']) {
    if (permissions.containsKey(resource)) {
      permissions[resource]!.remove(role);
    }
  }

  void listPermissions() {
    print('Permissions:');
    permissions.forEach((resource, roles) {
      print('  $resource: ${roles.join(', ')}');
    });
  }

  @override
  String toString() => '$name: ${permissions.length} resources, ${permissions.keys.length} roles';
}

class RoleHierarchy {
  final Map<String, String> parent = {};

  void setParent(String child, String parentRole) {
    parent[child] = parentRole;
  }

  String getParent(String role) => parent[role] ?? '';
}

