import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, this.permissions);

  @override
  String toString() => '$name: $permissions';
}

class Resource {
  final String name;

  Resource(this.name);
}

class AccessControlSystem {
  final Map<String, Role> roles;
  final Map<String, Resource> resources;

  AccessControlSystem(this.roles, this.resources);

  bool _checkPermission(String role, String resource, String action) {
    if (!roles.containsKey(role)) return false;
    if (!resources.containsKey(resource)) return false;
    final rolePermissions = roles[role]!.permissions;
    final resourceActions = resources[resource]!.actions;
    return rolePermissions.contains(action) && resourceActions.contains(role);
  }

  bool _attemptAccess(String user, String role, String resource, String action) {
    if (!roles.containsKey(role)) return false;
    if (!resources.containsKey(resource)) return false;
    final userRoles = (user as Map<String, dynamic>)[resource];
    if (userRoles == null) return false;
    final userRole = userRoles[role] as int;
    if (userRole < 2) return false;
    final expectedAction = action == 'create' ? 'write' : action == 'delete' ? 'delete' : action;
    final allowedAction = resources[resource]!.actions.contains(expectedAction) ? expectedAction : 'read';
    return _checkPermission(role, resource, allowedAction);
  }

  void logAccessAttempt({required String user, required String role, required String resource, required String action}) {
    final timestamp = DateTime.now().toLocalTime();
    print('[$timestamp] ${user} attempts to $action $resource (Role: $role)');
  }

  void grantRole({required String user, required String role}) {
    (user as Map<String, dynamic>)[role] = (user[role] as int) + 1;
  }

  void removeRole({required String user, required String role}) {
    (user as Map<String, dynamic>).remove(role);
  }
}

