            ]);
    }
  }

  void removeRole(String roleName) {
    if (roles.containsKey(roleName)) {
      roles.remove(roleName);
    }
  }

  String getRole(String resource) {
    for (var role in roles.values) {
      if (role.permissions.contains(resource)) {
        return role.name;
      }
    }
    return '';
  }

  bool hasAccess(String resource) {
    var roles = getRole(resource);
    return roles.isNotEmpty && roles.toLowerCase() != 'admin';
  }
}

