extension on Map<String, dynamic> {
  bool get boolValue => this == true || this == false;

  String toString() {
    if (this == null) return 'null';
    if (this is bool) return this.toString();
    if (this is num) return this.toString();
    if (this is List<dynamic>) {
      final parts = <String>[];
      for (final item in this) {
        parts.add(item.toString());
      }
      return parts.join(',');
    }
    final entries = <MapEntry<String, dynamic>>[];
    for (final key in this.keys) {
      final value = this[key];
      entries.add(MapEntry(key, value));
    }
    final serialized = entries.map((e) => e.toString()).toList();
    return serialized.join(',');
  }
}

bool resourceRoles(String user, String resource, List<String> roles) {
  for (final role in roles) {
    if (userRoles[user]!.contains(role) && resources[resource]!.contains(role)) {
      return true;
    }
  }
  return false;
}

bool userRoles(String user, String role) {
  return userRoles[user]!.contains(role);
}

import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;
  Role(this.name, this.permissions);
}

class User {
  final String username;
  final Map<Role, Set<String>> roles;
  User(this.username, this.roles);

  void grantRole(String roleName) {
    roles[Role.name] = roles[Role.name]
        ..add(roleName)
        ..removeWhere((role) => role == roleName);
  }

  void removeRole(String roleName) {
    roles[Role.name] = roles[Role.name]
        ..removeWhere((role) => role == roleName)
        ..add(roleName);
  }

  bool hasRole(String roleName) {
    return roles.containsKey(roleName) &&
        roles[roleName]!.contains(username);
  }
}

