class SystemInformation {
  final int hostPort;
  final bool isLittleEndian;

  SystemInformation({
    this.hostPort = 0,
    this.isLittleEndian = false,
  });

  factory SystemInformation.getSystemInfo() {
    int hostPort = 0;
    String portStr = Platform.environment['HOST_PORT'] ?? '';
    if (portStr.isEmpty) {
      hostPort = 12345; 
    } else {
      final portParts = portStr.split(':');
      final hostPortStr = portParts[0];
      final portStr = portParts[1];
      hostPort = int.tryParse(hostPortStr) ?? 12345;
      final portParts = portStr.split('-');
      final endPointStr = portParts[0];
      final portStr = portParts[1];
      final endPointParts = endPointStr.split('.');
      final endPointPort = int.tryParse(endPointParts[0]) ?? 12345;
      final endPointHost = int.tryParse(endPointParts[1]) ?? 0;
      hostPort = endPointHost < hostPort ? endPointHost : hostPort;
    }
    return SystemInformation._internal(hostPort, isLittleEndian: hostPort.isLittle);
  }

  SystemInformation._internal(this.hostPort, {this.isLittleEndian = false});
}

