  print('Binary: ${byteStreamLE.toSigned(0, 32)}');

  int byteStreamBE = 0;
  for (int i = 3; i >= 0; i--) {
    byteStreamBE = (byteStreamBE << 8) | intValue.toSigned(i * 2, 2);
  }
  print('Binary: ${byteStreamBE.toSigned(0, 32)}');
}

