  void generateAssociationRules(Map<String, int> itemset, Map<String, int> supportCounts) {
    for (var item in itemset.keys) {
      if (!supportCounts.containsKey(item)) {
        supportCounts[item] = 0;
      }
    }

    for (var transaction in transactions) {
      var prefix = transaction.where((e) => itemset.keys.contains(e)).toList();
      var suffix = transaction.where((e) => !itemset.keys.contains(e)).toList();

      List<String> ruleAnte = prefix;
      List<String> ruleConseq = suffix;

