class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  Rectangle.square(double side)
      : this(x: side / 2, y: side / 2, width: side, height: side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(
          x: p1.x < p2.x ? p1.x : p2.x,
          y: p1.y < p2.y ? p1.y : p2.y,
          width: (p1.x < p2.x ? p2.x : p1.x) - p1.x,
          height: (p1.y < p2.y ? p2.y : p1.y) - p1.y,
        );

  Rectangle.centered(double centerX, double centerY, double halfWidth,
      double halfHeight)
      : this(
          x: centerX - halfWidth,
          y: centerY - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  Rectangle.fromCenter(double centerX, double centerY, double radius)
      : this(
          x: centerX - radius,
          y: centerY - radius,
          width: 2 * radius,
          height: 2 * radius,
        );

  Rectangle get bounds =>
      Rectangle.fromPoints(Point(x, y), Point(x + width, y + height));

  Rectangle get left =>
      Rectangle.centered(x, y, width / 2, height);

  Rectangle get right =>
      Rectangle.centered(x + width, y, width / 2, height);

  Rectangle get bottom =>
      Rectangle.centered(x, y + height, width, height / 2);

  Rectangle get top =>
      Rectangle.centered(x, y, width, height / 2);

  bool contains(Point p) =>
      p.x >= x && p.x < x + width && p.y >= y && p.y < y + height;

  bool contains(Rectangle other) =>
      other.x < x + width && other.x + other.width > x &&
      other.y < y + height && other.y + other.height > y;

  bool intersects(Rectangle other) =>
      !((other.x > x + width) ||
          (other.x + other.width < x) ||
          (other.y > y + height) ||
          (other.y + other.height < y)));

  @override
  String toString() =>
      'Rectangle(center: (${x}, ${y}), halfWidth: $width, halfHeight: $height)';
}

