/// A class representing a rectangle in 2D space.
class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  bool contains(Point p) =>
      p.x >= x && p.x < x + width && p.y >= y && p.y < y + height;

  bool overlaps(Rectangle other) =>
      !contains(other.x - other.width, other.y - other.height) &&
      !other.contains(x, y, width, height);

  Rectangle union(Rectangle other) =>
      Rectangle(x: x < other.x ? x : other.x,
              y: y < other.y ? y : other.y,
              width: width > other.width ? width : other.width,
              height: height > other.height ? height : other.height);

  Rectangle intersection(Rectangle other) =>
      Rectangle(x: x < other.x ? x : other.x,
              y: y < other.y ? y : other.y,
              width: width > other.width ? width : other.width,
              height: height > other.height ? height : other.height);

  Rectangle subtract(Rectangle other) =>
      Rectangle(x: x < other.x ? x : other.x - width,
              y: y < other.y ? y : other.y - height,
              width: width > other.width ? width - other.width : 0,
              height: height > other.height ? height - other.height : 0);

  Rectangle inflate(double amount) =>
      Rectangle(x: x - amount, y: y - amount, width: width + 2 * amount, height: height + 2 * amount);

  Rectangle resize(double newWidth, double newHeight) =>
      Rectangle(x: x, y: y, width: newWidth, height: newHeight);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

