  if (k <= 0 || k > n) {
    print('Invalid number of clusters ($k). Exiting.');
    return;
  }

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  final List<List<double>> centroids = List.generate(k, (_) => List.filled(data[0].length, 0.0));

  for (int i = 0; i < k; i++) {

    final int idx = rng.nextInt(n); 

    for (int j = 0; j < data[idx].length; j++) {
      centroids[i][j] = data[idx][j];
    }
  }

  final Set<int> visited = {};

  for (int iter = 0; iter < 100; iter++) {

    final List<List<double>> newCentroids = List.generate(k, (_) => List.filled(data[0].length, 0.0));

    for (int i = 0; i < n; i++) {

      int bestIdx = 0;
      double bestDist = double.infinity;

      for (int j = 1; j < k; j++) {
        final dist = distance(data[i], centroids[j]);
        if (dist < bestDist) {
          bestDist = dist;
          bestIdx = j;
        }
      }

      newCentroids[bestIdx] = List<double>.from(centroids[bestIdx]);

      if (!visited.contains(i)) {

        final dists = List<double>.filled(k, double.infinity);

        for (int j = 0; j < k; j++) {
          dists[j] = distance(data[i], centroids[j]);
        }

