    final double dist = double.infinity;
    for (int j = 0; j < k; j++) {
      for (int idx in data) {
        final newDist = distance(idx, centroids[j]);
        if (newDist < dist) {
          dist = newDist;
        }
      }
    }

    if (dist == double.infinity) {
      print('Converged in $iter iteration(s).');
      break;
    }

    centroids = newCentroids;
  }
