  ];

  final numClusters = 2; 

  double euclideanDistance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (var i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  final centroids = <List<double>>[];
  final clusters = List<Set<int>>.generate(numClusters, (_) => <int>{});

  for (var i = 0; i < data.length; i++) {
    final idx = rng.nextInt(numClusters);
    clusters[idx].add(i);
    centroids.add([data[i][0], data[i][1]]);
  }

  double distanceTo(List<double> a, List<double> b) =>
      euclideanDistance(a, b);

  double distanceTo(List<double> a, List<List<double>>) {
    double minDist = double.infinity;
    for (final c in centroids) {
      final d = distanceTo(a, c);
      if (d < minDist) minDist = d;
    }
    return minDist;
  }

  double distanceTo(List<List<double>>) {
    double minDist = double.infinity;
    for (final a in centroids) {
      for (final b in centroids) {
        if (a == b) continue;
        final d = distanceTo(a, b);
        if (d < minDist) minDist = d;
      }
    }
    return minDist;
  }

  List<double> centroidTo(List<double>) {
    final result = <double>[];
    for (var i = 0; i < centroids.length; i++) {
      final d = distanceTo(centroids[i], result);
      if (d < distanceTo(result)) result[i] = centroids[i][i];
    }
    return result;
  }

  bool converged = false;
  var iter = 0;
  while (!converged) {
    converged = true;
    iter++;

    final newCentroids = <List<double>>[];

    for (var idx in clusters) {
      if (idx.isEmpty) {
        newCentroids.add([0.0, 0.0]);
      } else {
        final points = idx.toList();
        newCentroids.add([
          (points.first[0] + points.last[0]) / 2.0,
          (points.first[1] + points.last[1]) / 2.0
        ]);
      }
    }

    final newDist = distanceTo(newCentroids);
    for (var i = 0; i < newCentroids.length; i++) {
      if (newCentroids[i][i] != centroids[i][i]) converged = false;
    }

    if (converged) break;

    centroids = newCentroids;
    clusters = List<Set<int>>.generate(numClusters, (_) => <int>{});

    for (var i = 0; i < data.length; i++) {
      final minDist = double.infinity;
      var bestIdx = -1;
      for (var j = 0; j < numClusters; j++) {
        final d = distanceTo(data[i], centroids[j]);
        if (d < minDist) { minDist = d; bestIdx = j; }
      }
      clusters[bestIdx].add(i);
    }
  }

  print('Converged in $iter iteration(s).');
  print('Cluster ${clusters.index(data[0])}:');
  for (final idx in clusters[0]) {
    print('  Points: $idx');
  }
}

