/// Dart's [Stream] is a powerful tool for creating asynchronous sequences
/// of values that are computed on-demand. It allows you to write
/// asynchronous code that doesn't block the main thread.

/// Our [Counter] class listens to value changes from a [Stream]
/// and emits its own value as a result of the received change.
/// It also emits a "Done" value when the source stream completes.
class Counter {
  final Stream<int> values;

  Counter(this.values);

  Stream<int> count(int start) async* {
    int value = start;
    await for (var changed in values) {
      value = changed == 0 ? 0 : value + changed;
      yield value;
    }
    yield "Done.";
  }
}

